 s=f.read_text(); s=s.replace('\\u00a0',' ')
 print('\\nFILE',f.name)
 page='?'
 lines=s.splitlines()
 hits=set()
 for i,l in enumerate(lines):
  if re.search(r'compet|exclusiv|restrict|other (?:supplier|manufacturer)|similar product',l,re.I):
